import { useMemo, useState } from "react";
import { trpc } from "../lib/trpc";
import { AlertTriangle, BarChart3, Building2, CalendarClock, CheckCircle2, ClipboardCheck, FileCheck2, FileText, Home, Landmark, LoaderCircle, MapPin, Receipt, RefreshCw, ShieldCheck, UploadCloud, Users, WalletCards, Wrench, XCircle } from "lucide-react";

const TABS = [["overview", "Overview"], ["portfolio", "Portfolio"], ["leasing", "Leasing"], ["billing", "Rent & Billing"], ["maintenance", "Maintenance"], ["finance", "Finance"], ["documents", "Documents"], ["reports", "Reports"]];
const unitTypes = ["Apartment", "House", "Commercial Space", "Office", "Shop", "Warehouse", "Parking", "Plot", "Room"];
const paymentMethods = ["Cash", "Bank Transfer", "Mobile Money", "Card", "Cheque", "Provider"];

function money(value) { return `TZS ${new Intl.NumberFormat("en-TZ", { maximumFractionDigits: 0 }).format(Number(value) || 0)}`; }
function dateText(value) { if (!value) return "Not available"; const d = new Date(value); return Number.isNaN(d.getTime()) ? String(value) : d.toLocaleDateString("en-TZ", { dateStyle: "medium", timeZone: "Africa/Dar_es_Salaam" }); }
function dateTime(value) { if (!value) return "Not available"; const d = new Date(value); return Number.isNaN(d.getTime()) ? String(value) : d.toLocaleString("en-TZ", { dateStyle: "medium", timeStyle: "short", timeZone: "Africa/Dar_es_Salaam" }); }
function randomKey() { return globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`; }
function tone(value) { if (["Active", "Available", "Occupied", "Paid", "Posted", "Approved", "Completed", "Matched", "Verified"].includes(value)) return "border-emerald-100 bg-emerald-50 text-emerald-700"; if (["Overdue", "Rejected", "Failed", "Terminated", "Emergency", "Variance"].includes(value)) return "border-rose-100 bg-rose-50 text-rose-700"; if (["Pending", "Pending Approval", "Provider Pending", "Needs Review", "Under Review", "Open", "Assigned"].includes(value)) return "border-amber-100 bg-amber-50 text-amber-700"; return "border-slate-200 bg-slate-50 text-slate-600"; }
function Badge({ children }) { return <span className={`inline-flex items-center rounded-full border px-2 py-1 text-[10px] font-bold ${tone(children)}`}>{children || "Unknown"}</span>; }
function Card({ children, className = "" }) { return <section className={`rounded-2xl border border-slate-200/80 bg-white p-4 shadow-sm ${className}`}>{children}</section>; }
function Field({ label, children, hint }) { return <label className="block"><span className="mb-1.5 block text-[10.5px] font-bold uppercase tracking-[.08em] text-slate-500">{label}</span>{children}{hint && <span className="mt-1 block text-[10px] text-slate-400">{hint}</span>}</label>; }
function Input(props) { return <input {...props} className={`w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-[12px] text-slate-800 outline-none transition focus:border-emerald-400 focus:ring-2 focus:ring-emerald-100 ${props.className || ""}`} />; }
function Select(props) { return <select {...props} className={`w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-[12px] text-slate-800 outline-none transition focus:border-emerald-400 focus:ring-2 focus:ring-emerald-100 ${props.className || ""}`} />; }
function ActionButton({ children, onClick, disabled, variant = "primary", type = "button" }) { const styles = variant === "secondary" ? "border-slate-200 bg-white text-slate-700 hover:bg-slate-50" : variant === "danger" ? "border-rose-200 bg-rose-50 text-rose-700 hover:bg-rose-100" : "border-emerald-700 bg-emerald-700 text-white hover:bg-emerald-800"; return <button type={type} onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-xl border px-3.5 py-2.5 text-[11px] font-bold transition active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50 ${styles}`}>{children}</button>; }
function Metric({ icon: Icon, label, value, detail, accent = "emerald" }) { const colours = { emerald: "bg-emerald-50 text-emerald-700", blue: "bg-blue-50 text-blue-700", amber: "bg-amber-50 text-amber-700", violet: "bg-violet-50 text-violet-700" }; return <div className="rounded-2xl border border-slate-200/80 bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><span className={`grid h-9 w-9 place-items-center rounded-xl ${colours[accent] || colours.emerald}`}><Icon size={17} /></span><span className="text-[10px] font-semibold uppercase tracking-[.13em] text-slate-400">TZS</span></div><p className="mt-4 text-[11px] font-bold uppercase tracking-[.12em] text-slate-400">{label}</p><p className="mt-1 truncate text-[20px] font-black tracking-tight text-slate-900">{value}</p><p className="mt-1 text-[10.5px] leading-4 text-slate-500">{detail}</p></div>; }
function Modal({ title, children, close }) { return <div className="fixed inset-0 z-[90] flex items-end justify-center bg-slate-950/40 p-3 sm:items-center"><div role="dialog" aria-modal="true" aria-label={title} className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-5 shadow-2xl"><div className="mb-4 flex items-center justify-between gap-3"><div><h2 className="text-[17px] font-black text-slate-900">{title}</h2><p className="mt-1 text-[11px] text-slate-500">Saved only after the server confirms the operation.</p></div><button type="button" aria-label={`Close ${title}`} onClick={close}><XCircle size={18} className="text-slate-400" /></button></div>{children}</div></div>; }

function CustomerPortal({ query, action }) {
  const data = query.data || {};
  const tenant = data.tenant || {};
  const invoices = data.invoices || [];
  const payments = data.payments || [];
  const requests = data.maintenanceRequests || [];
  const notifications = data.notifications || [];
  const [notice, setNotice] = useState(null);
  const [maintenance, setMaintenance] = useState({ title: "", description: "", priority: "Medium" });
  const [payment, setPayment] = useState({ invoiceId: "", amount: "", paymentMethod: "Mobile Money" });
  const submitMaintenance = (event) => { event.preventDefault(); action.mutate({ action: "CREATE_MAINTENANCE_REQUEST", payload: { ...maintenance, title: maintenance.title, description: maintenance.description } }, { onSuccess: () => { setNotice({ kind: "success", text: "Maintenance request recorded." }); setMaintenance({ title: "", description: "", priority: "Medium" }); query.refetch(); }, onError: (error) => setNotice({ kind: "error", text: error.message }) }); };
  const submitPayment = (event) => { event.preventDefault(); action.mutate({ action: "RECORD_PAYMENT", payload: { invoiceId: payment.invoiceId, amount: Number(payment.amount), paymentMethod: payment.paymentMethod, idempotencyKey: randomKey() } }, { onSuccess: (result) => { setNotice({ kind: "success", text: result?.status === "Provider Pending" ? "Payment intent recorded; provider confirmation is still pending." : "Payment recorded." }); setPayment({ invoiceId: "", amount: "", paymentMethod: "Mobile Money" }); query.refetch(); }, onError: (error) => setNotice({ kind: "error", text: error.message }) }); };
  return <div className="space-y-5" aria-label="Property Management tenant portal"><header className="rounded-2xl bg-gradient-to-br from-[#123B3A] via-[#176B5D] to-[#16A34A] p-5 text-white shadow-sm sm:p-7"><div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><div className="mb-2 flex items-center gap-2 text-[10px] font-black uppercase tracking-[.18em] text-emerald-100"><Home size={14} /> Tanzania Property Tenant Portal</div><h1 className="text-[24px] font-black tracking-tight sm:text-[30px]">Your home, lease, and rent in view</h1><p className="mt-2 max-w-2xl text-[12px] leading-5 text-emerald-50/80">This portal is limited to the authenticated tenant profile linked to your account. It does not expose internal portfolio, owner, or other tenant records.</p></div><span className="rounded-xl border border-white/15 bg-white/10 px-3 py-2 text-[10.5px] font-semibold"><ShieldCheck size={15} className="mr-1 inline" /> Tenant-only access</span></div></header>{notice && <div role="status" className={`rounded-xl border px-3 py-2.5 text-[11px] ${notice.kind === "error" ? "border-rose-200 bg-rose-50 text-rose-800" : "border-emerald-200 bg-emerald-50 text-emerald-800"}`}>{notice.text}</div>}{query.isLoading && <Card><RefreshCw size={16} className="mr-2 inline animate-spin" /> Loading server-confirmed tenant state…</Card>}{query.error && <Card className="text-rose-700"><XCircle size={18} className="mr-2 inline" />{query.error.message}. A linked tenant profile is required before this portal can display data.</Card>}{!query.isLoading && !query.error && <><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric icon={Home} label="Active leases" value={data.leases?.length || 0} detail={tenant.fullName || "Linked tenant"} /><Metric icon={Receipt} label="Outstanding rent" value={money(invoices.reduce((sum, row) => sum + Math.max(0, Number(row.totalAmount || 0) - Number(row.amountPaid || 0)), 0))} detail="Open invoice balance" accent="amber" /><Metric icon={Wrench} label="Maintenance" value={requests.filter((row) => !["Closed", "Cancelled"].includes(row.status)).length} detail="Open requests" accent="blue" /><Metric icon={BellIcon} label="Unread notices" value={notifications.filter((row) => row.status !== "Read").length} detail="In-app updates" accent="violet" /></div><div className="grid gap-4 lg:grid-cols-[1.15fr_.85fr]"><Card><div className="flex items-center justify-between gap-2"><div><h2 className="text-[15px] font-black text-slate-900">My lease and invoices</h2><p className="mt-1 text-[11px] text-slate-500">TZS amounts and Africa/Dar_es_Salaam dates are server-backed.</p></div><Badge>{tenant.kycStatus || "Pending"}</Badge></div><div className="mt-4 space-y-2">{(data.leases || []).map((lease) => <div key={lease.id} className="rounded-xl border border-slate-100 p-3"><div className="flex items-center justify-between gap-2"><p className="font-mono text-[11.5px] font-bold text-slate-800">{lease.leaseNumber}</p><Badge>{lease.status}</Badge></div><p className="mt-1 text-[10.5px] text-slate-500">{dateText(lease.startDate)} – {dateText(lease.endDate)} · {money(lease.rentAmount)} / {lease.rentFrequency}</p></div>)}{!data.leases?.length && <p className="rounded-xl border border-dashed border-slate-200 p-5 text-center text-[11px] text-slate-400">No lease is linked to this account yet.</p>}</div><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[580px] text-left text-[11px]"><thead className="border-b border-slate-100 text-[10px] uppercase tracking-wide text-slate-400"><tr><th className="pb-2">Invoice</th><th className="pb-2">Due</th><th className="pb-2">Total</th><th className="pb-2">Balance</th><th className="pb-2">Status</th></tr></thead><tbody>{invoices.map((row) => <tr key={row.id} className="border-b border-slate-50"><td className="py-3 font-mono font-bold">{row.invoiceNumber}</td><td className="py-3">{dateText(row.dueDate)}</td><td className="py-3">{money(row.totalAmount)}</td><td className="py-3 font-bold">{money(Math.max(0, Number(row.totalAmount || 0) - Number(row.amountPaid || 0)))}</td><td className="py-3"><Badge>{row.status}</Badge></td></tr>)}{!invoices.length && <tr><td colSpan="5" className="py-8 text-center text-slate-400">No invoices recorded.</td></tr>}</tbody></table></div></Card><div className="space-y-4"><Card><h2 className="text-[15px] font-black text-slate-900">Create a payment intent</h2><p className="mt-1 text-[11px] leading-4 text-slate-500">Mobile-money, bank, card, and provider intents remain pending until an approved adapter confirms them. No external call is made here.</p><form onSubmit={submitPayment} className="mt-4 space-y-3"><Field label="Invoice"><Select required value={payment.invoiceId} onChange={(event) => setPayment({ ...payment, invoiceId: event.target.value })}><option value="">Select outstanding invoice</option>{invoices.filter((row) => Number(row.totalAmount || 0) > Number(row.amountPaid || 0)).map((row) => <option key={row.id} value={row.id}>{row.invoiceNumber} · balance {money(Number(row.totalAmount || 0) - Number(row.amountPaid || 0))}</option>)}</Select></Field><Field label="Amount (TZS)"><Input required min="1" step="1" type="number" value={payment.amount} onChange={(event) => setPayment({ ...payment, amount: event.target.value })} /></Field><Field label="Method"><Select value={payment.paymentMethod} onChange={(event) => setPayment({ ...payment, paymentMethod: event.target.value })}>{paymentMethods.filter((item) => item !== "Cash").map((item) => <option key={item}>{item}</option>)}</Select></Field><ActionButton type="submit" disabled={action.isPending}>Record provider-safe payment intent</ActionButton></form></Card><Card><h2 className="text-[15px] font-black text-slate-900">Request maintenance</h2><form onSubmit={submitMaintenance} className="mt-4 space-y-3"><Field label="Title"><Input required value={maintenance.title} onChange={(event) => setMaintenance({ ...maintenance, title: event.target.value })} /></Field><Field label="Priority"><Select value={maintenance.priority} onChange={(event) => setMaintenance({ ...maintenance, priority: event.target.value })}><option>Low</option><option>Medium</option><option>High</option><option>Emergency</option></Select></Field><Field label="Description"><textarea required value={maintenance.description} onChange={(event) => setMaintenance({ ...maintenance, description: event.target.value })} className="min-h-24 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-[12px]" /></Field><ActionButton type="submit" disabled={action.isPending}><Wrench size={14} /> Submit request</ActionButton></form></Card></div></div><Card><h2 className="text-[15px] font-black text-slate-900">Recent payment and notice evidence</h2><div className="mt-4 space-y-2">{[...payments.slice(0, 5), ...notifications.slice(0, 5)].map((row) => <div key={row.id} className="flex items-center justify-between gap-3 rounded-xl border border-slate-100 p-3"><div><p className="text-[11px] font-bold text-slate-800">{row.paymentNumber || row.title}</p><p className="text-[10.5px] text-slate-500">{row.amount ? money(row.amount) : row.body} · {dateTime(row.createdAt || row.paidAt)}</p></div><Badge>{row.status}</Badge></div>)}{!payments.length && !notifications.length && <p className="text-[11px] text-slate-400">No recent payment or notice records.</p>}</div></Card></>}</div>;
}
function BellIcon(props) { return <span className="inline-flex"><svg {...props} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9" /><path d="M13.73 21a2 2 0 0 1-3.46 0" /></svg></span>; }

function Composer({ kind, snapshot, mutate, close }) {
  const [form, setForm] = useState({});
  const set = (key, value) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (event) => { event.preventDefault(); const values = { ...form }; const numeric = ["areaSqm", "rentAmount", "serviceChargeAmount", "depositAmount", "amount", "proposedRent", "rate", "flatAmount", "estimatedCost", "actualCost", "readingValue", "commissionRate", "askingAmount", "premium", "budgetAmount", "keysCount", "fiscalYear"]; numeric.forEach((key) => { if (values[key] !== undefined && values[key] !== "") values[key] = Number(values[key]); }); if (kind === "SUBMIT_APPLICATION") values.idempotencyKey = randomKey(); mutate.mutate({ action: kind, payload: values }, { onSuccess: () => close(), onError: () => undefined }); };
  const portfolios = snapshot.portfolios || []; const buildings = snapshot.buildings || []; const owners = snapshot.owners || []; const units = snapshot.units || []; const tenants = snapshot.tenants || []; const leases = snapshot.leases || []; const listings = snapshot.listings || []; const requests = snapshot.maintenanceRequests || []; const invoices = snapshot.invoices || []; const workOrders = snapshot.workOrders || []; const insurances = snapshot.insurances || []; const budgets = snapshot.budgets || []; const serviceCharges = snapshot.serviceCharges || []; const handovers = snapshot.handovers || [];
  const config = { REGISTER_PORTFOLIO: ["Register portfolio", <><Field label="Portfolio code"><Input required onChange={(e) => set("portfolioCode", e.target.value)} /></Field><Field label="Name"><Input required onChange={(e) => set("name", e.target.value)} /></Field><Field label="Description"><Input onChange={(e) => set("description", e.target.value)} /></Field></>], REGISTER_BUILDING: ["Register building", <><Field label="Portfolio"><Select required onChange={(e) => set("portfolioId", e.target.value)}><option value="">Select portfolio</option>{portfolios.map((p) => <option key={p.id} value={p.id}>{p.portfolioCode} · {p.name}</option>)}</Select></Field><Field label="Property code"><Input required onChange={(e) => set("propertyCode", e.target.value)} /></Field><Field label="Building / property name"><Input required onChange={(e) => set("name", e.target.value)} /></Field><Field label="Property type"><Select onChange={(e) => set("propertyType", e.target.value)}><option>Building</option><option>Apartment Block</option><option>House</option><option>Commercial Centre</option><option>Office Block</option><option>Warehouse</option><option>Mixed Use</option></Select></Field><Field label="Address"><Input onChange={(e) => set("address", e.target.value)} /></Field><div className="grid gap-3 sm:grid-cols-3"><Field label="Region"><Input onChange={(e) => set("region", e.target.value)} /></Field><Field label="District"><Input onChange={(e) => set("district", e.target.value)} /></Field><Field label="Ward"><Input onChange={(e) => set("ward", e.target.value)} /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Latitude"><Input type="number" step="any" onChange={(e) => set("latitude", e.target.value)} /></Field><Field label="Longitude"><Input type="number" step="any" onChange={(e) => set("longitude", e.target.value)} /></Field></div></>], REGISTER_UNIT: ["Register unit", <><Field label="Building"><Select required onChange={(e) => set("buildingId", e.target.value)}><option value="">Select building</option>{buildings.map((b) => <option key={b.id} value={b.id}>{b.propertyCode} · {b.name}</option>)}</Select></Field><Field label="Unit code"><Input required onChange={(e) => set("unitCode", e.target.value)} /></Field><Field label="Unit type"><Select onChange={(e) => set("unitType", e.target.value)}>{unitTypes.map((item) => <option key={item}>{item}</option>)}</Select></Field><Field label="Owner"><Select onChange={(e) => set("ownerId", e.target.value || null)}><option value="">No linked owner yet</option>{owners.map((o) => <option key={o.id} value={o.id}>{o.legalName}</option>)}</Select></Field><div className="grid gap-3 sm:grid-cols-3"><Field label="Area m²"><Input type="number" min="0" step="any" onChange={(e) => set("areaSqm", e.target.value)} /></Field><Field label="Rent (TZS)"><Input required type="number" min="0" step="1" onChange={(e) => set("rentAmount", e.target.value)} /></Field><Field label="Deposit (TZS)"><Input type="number" min="0" step="1" onChange={(e) => set("depositAmount", e.target.value)} /></Field></div><Field label="Service charge (TZS)"><Input type="number" min="0" step="1" onChange={(e) => set("serviceChargeAmount", e.target.value)} /></Field></>], REGISTER_LISTING: ["Register property listing", <><Field label="Unit"><Select required onChange={(e) => set("unitId", e.target.value)}><option value="">Select unit</option>{units.map((u) => <option key={u.id} value={u.id}>{u.unitCode} · {money(u.rentAmount)}</option>)}</Select></Field><Field label="Listing type"><Select onChange={(e) => set("listingType", e.target.value)}><option>Rent</option><option>Sale</option><option>Leasehold</option></Select></Field><Field label="Asking amount (TZS)"><Input required type="number" min="0" step="1" onChange={(e) => set("askingAmount", e.target.value)} /></Field><Field label="Commission rate"><Input type="number" min="0" step="0.0001" onChange={(e) => set("commissionRate", e.target.value)} /></Field><Field label="Agent"><Select onChange={(e) => set("agentId", e.target.value || null)}><option value="">No agent</option>{(snapshot.agents || []).map((a) => <option key={a.id} value={a.id}>{a.agentCode} · {a.fullName}</option>)}</Select></Field><Field label="Description"><Input onChange={(e) => set("description", e.target.value)} /></Field></>], REGISTER_OWNER: ["Register owner / landlord", <><Field label="Legal name"><Input required onChange={(e) => set("legalName", e.target.value)} /></Field><Field label="Tanzania phone"><Input required placeholder="0712345678" onChange={(e) => set("phone", e.target.value)} /></Field><Field label="Email"><Input type="email" onChange={(e) => set("email", e.target.value)} /></Field><Field label="National ID"><Input onChange={(e) => set("nationalId", e.target.value)} /></Field><Field label="TIN"><Input onChange={(e) => set("tin", e.target.value)} /></Field></>], REGISTER_TENANT: ["Onboard tenant", <><Field label="Tenant code"><Input required onChange={(e) => set("tenantCode", e.target.value)} /></Field><Field label="Full name"><Input required onChange={(e) => set("fullName", e.target.value)} /></Field><Field label="Tanzania phone"><Input required placeholder="0712345678" onChange={(e) => set("phone", e.target.value)} /></Field><Field label="Email"><Input type="email" onChange={(e) => set("email", e.target.value)} /></Field><Field label="National ID"><Input onChange={(e) => set("nationalId", e.target.value)} /></Field><Field label="Address"><Input onChange={(e) => set("address", e.target.value)} /></Field></>], CREATE_LEASE: ["Create lease", <><Field label="Unit"><Select required onChange={(e) => set("unitId", e.target.value)}><option value="">Select unit</option>{units.filter((u) => ["Available", "Reserved"].includes(u.status)).map((u) => <option key={u.id} value={u.id}>{u.unitCode} · {money(u.rentAmount)}</option>)}</Select></Field><Field label="Tenant"><Select required onChange={(e) => set("tenantId", e.target.value)}><option value="">Select tenant</option>{tenants.map((t) => <option key={t.id} value={t.id}>{t.tenantCode} · {t.fullName}</option>)}</Select></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Start date"><Input required type="date" onChange={(e) => set("startDate", e.target.value)} /><span /></Field><Field label="End date"><Input required type="date" onChange={(e) => set("endDate", e.target.value)} /></Field></div><Field label="Rent (TZS)"><Input required type="number" min="0" step="1" onChange={(e) => set("rentAmount", e.target.value)} /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Service charge"><Input type="number" min="0" step="1" onChange={(e) => set("serviceChargeAmount", e.target.value)} /></Field><Field label="Deposit"><Input type="number" min="0" step="1" onChange={(e) => set("depositAmount", e.target.value)} /></Field></div><Field label="Frequency"><Select onChange={(e) => set("rentFrequency", e.target.value)}><option>Monthly</option><option>Quarterly</option><option>Biannual</option><option>Annual</option></Select></Field></>], RECORD_HANDOVER: ["Record lease handover", <><Field label="Lease"><Select required onChange={(e) => set("leaseId", e.target.value)}><option value="">Select lease</option>{leases.map((l) => <option key={l.id} value={l.id}>{l.leaseNumber}</option>)}</Select></Field><Field label="Handover type"><Select onChange={(e) => set("handoverType", e.target.value)}><option>Move In</option><option>Move Out</option></Select></Field><Field label="Keys count"><Input type="number" min="0" step="1" onChange={(e) => set("keysCount", e.target.value)} /></Field><Field label="Notes"><Input onChange={(e) => set("notes", e.target.value)} /></Field></>], GENERATE_INVOICE: ["Issue invoice", <><Field label="Lease"><Select required onChange={(e) => set("leaseId", e.target.value)}><option value="">Select lease</option>{leases.filter((l) => ["Active", "Renewal Due"].includes(l.status)).map((l) => <option key={l.id} value={l.id}>{l.leaseNumber} · {money(l.rentAmount)}</option>)}</Select></Field><Field label="Invoice type"><Select onChange={(e) => set("invoiceType", e.target.value)}><option>Rent</option><option>Service Charge</option><option>Deposit</option></Select></Field><Field label="Period start"><Input type="date" onChange={(e) => set("periodStart", e.target.value)} /></Field><Field label="Due date"><Input type="date" onChange={(e) => set("dueDate", e.target.value)} /></Field></>], REGISTER_INSURANCE: ["Register insurance policy", <><Field label="Property"><Select onChange={(e) => set("propertyId", e.target.value || null)}><option value="">No property</option>{buildings.map((b) => <option key={b.id} value={b.id}>{b.propertyCode} · {b.name}</option>)}</Select></Field><Field label="Unit"><Select onChange={(e) => set("unitId", e.target.value || null)}><option value="">No unit</option>{units.map((u) => <option key={u.id} value={u.id}>{u.unitCode}</option>)}</Select></Field><Field label="Insurer"><Input required onChange={(e) => set("insurer", e.target.value)} /></Field><Field label="Policy number"><Input required onChange={(e) => set("policyNumber", e.target.value)} /></Field><Field label="Cover type"><Input required onChange={(e) => set("coverType", e.target.value)} /></Field><Field label="Premium (TZS)"><Input type="number" min="0" step="1" onChange={(e) => set("premium", e.target.value)} /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Start date"><Input required type="date" onChange={(e) => set("startDate", e.target.value)} /></Field><Field label="End date"><Input required type="date" onChange={(e) => set("endDate", e.target.value)} /></Field></div></>], CREATE_BUDGET: ["Create portfolio budget", <><Field label="Portfolio"><Select onChange={(e) => set("portfolioId", e.target.value || null)}><option value="">All portfolios</option>{portfolios.map((p) => <option key={p.id} value={p.id}>{p.portfolioCode} · {p.name}</option>)}</Select></Field><Field label="Fiscal year"><Input required type="number" min="2000" max="2200" step="1" defaultValue={new Date().getFullYear()} onChange={(e) => set("fiscalYear", e.target.value)} /></Field><Field label="Category"><Input required onChange={(e) => set("category", e.target.value)} /></Field><Field label="Budget amount (TZS)"><Input required type="number" min="0" step="1" onChange={(e) => set("budgetAmount", e.target.value)} /></Field></>], REGISTER_SERVICE_CHARGE: ["Register service charge", <><Field label="Unit"><Select required onChange={(e) => set("unitId", e.target.value)}><option value="">Select unit</option>{units.map((u) => <option key={u.id} value={u.id}>{u.unitCode}</option>)}</Select></Field><Field label="Name"><Input required onChange={(e) => set("name", e.target.value)} /></Field><Field label="Amount (TZS)"><Input required type="number" min="0" step="1" onChange={(e) => set("amount", e.target.value)} /></Field><Field label="Frequency"><Select onChange={(e) => set("frequency", e.target.value)}><option>Monthly</option><option>Quarterly</option><option>Annual</option><option>One Time</option></Select></Field></>], RECORD_PAYMENT: ["Record payment", <><Field label="Invoice"><Select required onChange={(e) => set("invoiceId", e.target.value)}><option value="">Select invoice</option>{invoices.filter((i) => !["Paid", "Voided"].includes(i.status)).map((i) => <option key={i.id} value={i.id}>{i.invoiceNumber} · balance {money(Number(i.totalAmount || 0) - Number(i.amountPaid || 0))}</option>)}</Select></Field><Field label="Amount (TZS)"><Input required type="number" min="1" step="1" onChange={(e) => set("amount", e.target.value)} /></Field><Field label="Payment method"><Select required onChange={(e) => set("paymentMethod", e.target.value)}>{paymentMethods.map((item) => <option key={item}>{item}</option>)}</Select></Field><Field label="Provider code (label only)" hint="This is a non-secret provider label; no credentials are accepted here."><Input onChange={(e) => set("providerCode", e.target.value)} /></Field></>], CREATE_MAINTENANCE_REQUEST: ["Create maintenance request", <><Field label="Unit"><Select onChange={(e) => set("unitId", e.target.value || null)}><option value="">No unit selected</option>{units.map((u) => <option key={u.id} value={u.id}>{u.unitCode}</option>)}</Select></Field><Field label="Title"><Input required onChange={(e) => set("title", e.target.value)} /></Field><Field label="Priority"><Select onChange={(e) => set("priority", e.target.value)}><option>Low</option><option>Medium</option><option>High</option><option>Emergency</option></Select></Field><Field label="Description"><textarea required onChange={(e) => set("description", e.target.value)} className="min-h-24 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-[12px]" /></Field></>], ASSIGN_WORK_ORDER: ["Assign work order", <><Field label="Request"><Select required onChange={(e) => set("requestId", e.target.value)}><option value="">Select request</option>{requests.filter((r) => !["Closed", "Cancelled"].includes(r.status)).map((r) => <option key={r.id} value={r.id}>{r.requestNumber} · {r.title}</option>)}</Select></Field><Field label="Assigned profile ID (optional)"><Input onChange={(e) => set("assignedProfileId", e.target.value || null)} /></Field><Field label="Estimated cost"><Input type="number" min="0" step="1" onChange={(e) => set("estimatedCost", e.target.value)} /></Field><Field label="Due date"><Input type="date" onChange={(e) => set("dueDate", e.target.value)} /></Field></>], COMPLETE_WORK_ORDER: ["Complete work order", <><Field label="Work order"><Select required onChange={(e) => set("workOrderId", e.target.value)}><option value="">Select work order</option>{workOrders.filter((w) => w.status !== "Completed").map((w) => <option key={w.id} value={w.id}>{w.workOrderNumber}</option>)}</Select></Field><Field label="Actual cost"><Input type="number" min="0" step="1" onChange={(e) => set("actualCost", e.target.value)} /></Field><Field label="Completion note"><Input onChange={(e) => set("completionNote", e.target.value)} /></Field></>], CREATE_EXPENSE: ["Record expense", <><Field label="Category"><Input required onChange={(e) => set("category", e.target.value)} /></Field><Field label="Description"><Input required onChange={(e) => set("description", e.target.value)} /></Field><Field label="Amount (TZS)"><Input required type="number" min="1" step="1" onChange={(e) => set("amount", e.target.value)} /></Field><Field label="Property ID (optional)"><Input onChange={(e) => set("propertyId", e.target.value || null)} /></Field><Field label="Unit ID (optional)"><Input onChange={(e) => set("unitId", e.target.value || null)} /></Field></>], RECORD_METER_READING: ["Record utility meter reading", <><Field label="Meter ID"><Input required onChange={(e) => set("meterId", e.target.value)} /></Field><Field label="Reading value"><Input required type="number" min="0" step="any" onChange={(e) => set("readingValue", e.target.value)} /></Field><Field label="Reading date"><Input type="date" onChange={(e) => set("readingDate", e.target.value)} /></Field></>], ISSUE_NOTICE: ["Issue notice", <><Field label="Tenant ID"><Select required onChange={(e) => set("tenantId", e.target.value)}><option value="">Select tenant</option>{tenants.map((t) => <option key={t.id} value={t.id}>{t.fullName}</option>)}</Select></Field><Field label="Type"><Select onChange={(e) => set("noticeType", e.target.value)}><option>General</option><option>Rent Due</option><option>Overdue</option><option>Lease Expiry</option><option>Termination</option><option>Maintenance</option></Select></Field><Field label="Title"><Input required onChange={(e) => set("title", e.target.value)} /></Field><Field label="Body"><textarea required onChange={(e) => set("body", e.target.value)} className="min-h-24 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-[12px]" /></Field></>], CREATE_TAX_RULE: ["Configure tax or fee rule", <><Field label="Code"><Input required onChange={(e) => set("code", e.target.value)} /></Field><Field label="Name"><Input required onChange={(e) => set("name", e.target.value)} /></Field><Field label="Applies to"><Select onChange={(e) => set("appliesTo", e.target.value)}><option>Rent</option><option>Service Charge</option><option>Utility</option><option>Late Fee</option><option>Sale</option><option>All</option></Select></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Rate %"><Input type="number" min="0" step="0.0001" onChange={(e) => set("rate", e.target.value)} /></Field><Field label="Flat TZS"><Input type="number" min="0" step="1" onChange={(e) => set("flatAmount", e.target.value)} /></Field></div></>], RECORD_INSPECTION: ["Record inspection", <><Field label="Lease"><Select required onChange={(e) => set("leaseId", e.target.value)}><option value="">Select lease</option>{leases.map((l) => <option key={l.id} value={l.id}>{l.leaseNumber}</option>)}</Select></Field><Field label="Inspection type"><Select onChange={(e) => set("inspectionType", e.target.value)}><option>Move In</option><option>Routine</option><option>Move Out</option><option>Handover</option></Select></Field><Field label="Inspection date"><Input type="date" onChange={(e) => set("inspectionDate", e.target.value)} /></Field><Field label="Condition summary"><Input required onChange={(e) => set("conditionSummary", e.target.value)} /></Field></>], APPROVE_APPLICATION: ["Approve application", <Field label="Application"><Select required onChange={(e) => set("applicationId", e.target.value)}><option value="">Select application</option>{(snapshot.applications || []).filter((a) => ["Submitted", "Under Review"].includes(a.status)).map((a) => <option key={a.id} value={a.id}>{a.applicationNumber}</option>)}</Select></Field>] };
  const selected = config[kind]; if (!selected) return null; return <Modal title={selected[0]} close={close}><form onSubmit={submit} className="space-y-3">{selected[1]}<div className="flex justify-end gap-2 pt-2"><ActionButton variant="secondary" onClick={close}>Cancel</ActionButton><ActionButton type="submit" disabled={mutate.isPending}>{mutate.isPending ? <LoaderCircle size={14} className="animate-spin" /> : "Save confirmed workflow"}</ActionButton></div></form></Modal>;
}

function UploadPanel({ snapshot, upload, close }) {
  const [form, setForm] = useState({ entityType: "Building", entityId: "", documentType: "Title / lease document", title: "", fileName: "", contentType: "application/pdf", dataBase64: "", expiresAt: "" });
  const choose = (event) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => setForm((current) => ({ ...current, fileName: file.name, contentType: file.type || "application/octet-stream", dataBase64: String(reader.result || "") })); reader.readAsDataURL(file); };
  const submit = (event) => { event.preventDefault(); upload.mutate(form, { onSuccess: close }); };
  return <Modal title="Upload property document" close={close}><form onSubmit={submit} className="space-y-3"><Field label="Entity type"><Select value={form.entityType} onChange={(e) => setForm({ ...form, entityType: e.target.value })}><option>Building</option><option>Plot</option><option>Unit</option><option>Tenant</option><option>Lease</option><option>Inspection</option><option>Maintenance</option><option>Expense</option></Select></Field><Field label="Entity ID" hint="Use the confirmed server ID from the relevant table."><Input required value={form.entityId} onChange={(e) => setForm({ ...form, entityId: e.target.value })} /></Field><Field label="Document type"><Input required value={form.documentType} onChange={(e) => setForm({ ...form, documentType: e.target.value })} /></Field><Field label="Title"><Input required value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} /></Field><Field label="Expiry date"><Input type="date" value={form.expiresAt} onChange={(e) => setForm({ ...form, expiresAt: e.target.value })} /></Field><Field label="File"><Input required type="file" accept="application/pdf,image/*,.doc,.docx" onChange={choose} /></Field><p className="rounded-xl border border-blue-100 bg-blue-50/60 p-3 text-[10.5px] leading-4 text-blue-900">Bytes are sent only to the authenticated server storage boundary. The browser never receives a storage credential.</p><ActionButton type="submit" disabled={upload.isPending || !form.dataBase64}>{upload.isPending ? "Uploading…" : <><UploadCloud size={14} /> Upload and register</>}</ActionButton></form></Modal>;
}

export function PropertyManagementWorkspace({ currentUser }) {
  const role = String(currentUser?.role || "");
  const isTenant = role.toLowerCase().includes("tenant") || role.toLowerCase() === "customer";
  const [tab, setTab] = useState("overview"); const [composer, setComposer] = useState(null); const [uploadOpen, setUploadOpen] = useState(false); const [message, setMessage] = useState(null);
  const query = trpc.propertyManagement.snapshot.useQuery({ limit: 120 }, { retry: false, refetchOnWindowFocus: false });
  const action = trpc.propertyManagement.action.useMutation({ onSuccess: (result) => { setMessage({ kind: "success", text: result?.status ? `Server-confirmed status: ${result.status}.` : "Property workflow confirmed by the server." }); query.refetch(); }, onError: (error) => setMessage({ kind: "error", text: error.message || "The Property Management workflow could not be completed." }) });
  const upload = trpc.propertyManagement.uploadDocument.useMutation({ onSuccess: () => { setMessage({ kind: "success", text: "Document uploaded and registered by the server." }); query.refetch(); setUploadOpen(false); }, onError: (error) => setMessage({ kind: "error", text: error.message || "The document could not be uploaded." }) });
  const snapshot = query.data || {};
  const propertyError = query.error;
  const propertyErrorMessage = String(propertyError?.message || "");
  const propertyAccessDenied = propertyError?.data?.code === "FORBIDDEN" || /access|role|assigned|permission/i.test(propertyErrorMessage);
  if (isTenant) return <CustomerPortal query={query} action={action} />;
  const metrics = snapshot.metrics || {}; const permissions = snapshot.permissions || {}; const canManage = Boolean(permissions.canManage); const canFinance = Boolean(permissions.canFinance); const canApprove = Boolean(permissions.canApprove); const restricted = ["Property Agent", "Landlord / Owner", "Maintenance Staff"].includes(role);
  const visibleTabs = useMemo(() => TABS.filter(([id]) => !restricted || ["overview", "portfolio", "leasing", "maintenance", "documents", "reports"].includes(id)), [restricted]);
  const run = (actionName, payload) => action.mutate({ action: actionName, payload });
  const upcomingLeases = (snapshot.leases || []).filter((lease) => lease.status === "Active").sort((a, b) => String(a.endDate).localeCompare(String(b.endDate))).slice(0, 8);
  return <div className="space-y-5" aria-label="Property Management module"><header className="rounded-2xl bg-gradient-to-br from-[#142B3A] via-[#1F5C66] to-[#16A34A] p-5 text-white shadow-sm sm:p-7"><div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><div className="mb-2 flex items-center gap-2 text-[10px] font-black uppercase tracking-[.18em] text-emerald-100"><Building2 size={14} /> Tanzania Property Management</div><h1 className="text-[24px] font-black tracking-tight sm:text-[30px]">Portfolio, leases, rent, and property operations</h1><p className="mt-2 max-w-3xl text-[12px] leading-5 text-emerald-50/80">A server-confirmed workspace for property, ownership, tenant onboarding, leasing, TZS rent billing, maintenance, documents, reconciliation, and audit evidence.</p></div><span className="rounded-xl border border-white/15 bg-white/10 px-3 py-2 text-[10.5px] font-semibold"><ShieldCheck size={15} className="mr-1 inline" /> {permissions.canAudit ? "Governed access" : "Role-scoped access"}</span></div></header>{query.isLoading && <Card><RefreshCw size={16} className="mr-2 inline animate-spin" /> Loading server-confirmed property state…</Card>}{query.error && <Card className="text-rose-700"><XCircle size={18} className="mr-2 inline" /><strong>{propertyAccessDenied ? "Property Management access is restricted." : "Property Management data is temporarily unavailable."}</strong><p className="mt-1 text-[11px]">{propertyAccessDenied ? "Your profile is not assigned to a Property Management role for this workspace." : "No records were changed. The server-confirmed property snapshot could not be read. Retry the read or contact an administrator if the issue persists."}</p><ActionButton variant="secondary" onClick={() => query.refetch()}><RefreshCw size={14} /> Retry read</ActionButton></Card>}{message && <div role="status" className={`flex items-center justify-between gap-3 rounded-xl border px-3 py-2.5 text-[11px] ${message.kind === "error" ? "border-rose-200 bg-rose-50 text-rose-800" : "border-emerald-200 bg-emerald-50 text-emerald-800"}`}><span>{message.text}</span><button type="button" aria-label="Dismiss message" onClick={() => setMessage(null)}><XCircle size={14} /></button></div>}{!query.isLoading && !query.error && <><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric icon={Building2} label="Properties" value={metrics.propertyCount ?? 0} detail={`${metrics.portfolioCount ?? 0} portfolios`} /><Metric icon={Home} label="Occupancy" value={`${Number(metrics.occupancyRate || 0).toFixed(2)}%`} detail={`${metrics.occupiedUnits ?? 0} occupied · ${metrics.vacantUnits ?? 0} available`} accent="blue" /><Metric icon={WalletCards} label="Rental income" value={money(metrics.rentalIncome)} detail="Posted payments only" accent="violet" /><Metric icon={AlertTriangle} label="Outstanding rent" value={money(metrics.outstandingRent)} detail={`${metrics.overdueAccounts ?? 0} overdue accounts`} accent="amber" /></div><div className="flex gap-1 overflow-x-auto border-b border-slate-200 pb-1" role="tablist" aria-label="Property Management sections">{visibleTabs.map(([id, label]) => <button key={id} type="button" role="tab" aria-selected={tab === id} onClick={() => setTab(id)} className={`whitespace-nowrap rounded-lg px-3 py-2 text-[11px] font-bold transition ${tab === id ? "bg-emerald-700 text-white" : "text-slate-500 hover:bg-slate-100 hover:text-slate-800"}`}>{label}</button>)}</div><div className="flex flex-wrap gap-2">{canManage && <><ActionButton onClick={() => setComposer("REGISTER_PORTFOLIO")}><Building2 size={14} /> Add portfolio</ActionButton><ActionButton variant="secondary" onClick={() => setComposer("REGISTER_BUILDING")}><Landmark size={14} /> Add property</ActionButton><ActionButton variant="secondary" onClick={() => setComposer("REGISTER_UNIT")}><Home size={14} /> Add unit</ActionButton><ActionButton variant="secondary" onClick={() => setComposer("REGISTER_TENANT")}><Users size={14} /> Onboard tenant</ActionButton><ActionButton variant="secondary" onClick={() => setComposer("CREATE_LEASE")}><FileCheck2 size={14} /> Create lease</ActionButton></>}{canFinance && <><ActionButton variant="secondary" onClick={() => setComposer("GENERATE_INVOICE")}><Receipt size={14} /> Issue invoice</ActionButton><ActionButton variant="secondary" onClick={() => setComposer("RECORD_PAYMENT")}><WalletCards size={14} /> Record payment</ActionButton><ActionButton variant="secondary" onClick={() => setComposer("CREATE_EXPENSE")}><BarChart3 size={14} /> Record expense</ActionButton></>}{canManage && <><ActionButton variant="secondary" onClick={() => setComposer("CREATE_MAINTENANCE_REQUEST")}><Wrench size={14} /> New maintenance</ActionButton><ActionButton variant="secondary" onClick={() => setComposer("ISSUE_NOTICE")}><CalendarClock size={14} /> Issue notice</ActionButton></>}{canManage && <ActionButton variant="secondary" onClick={() => setUploadOpen(true)}><UploadCloud size={14} /> Upload document</ActionButton>}</div>{tab === "overview" && <div className="grid gap-4 lg:grid-cols-[1.15fr_.85fr]"><Card><div className="flex items-center justify-between gap-3"><div><h2 className="text-[15px] font-black text-slate-900">Portfolio control board</h2><p className="mt-1 text-[11px] text-slate-500">Numbers below are computed from persisted property rows and posted financial evidence.</p></div><Badge>{metrics.openMaintenance ? `${metrics.openMaintenance} maintenance open` : "Operations clear"}</Badge></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><div className="rounded-xl border border-slate-100 bg-slate-50/70 p-3"><p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Lease expiry watch</p><p className="mt-2 text-2xl font-black text-slate-900">{metrics.upcomingLeaseExpiries ?? 0}</p><p className="text-[10.5px] text-slate-500">Active leases ending within 90 days</p></div><div className="rounded-xl border border-slate-100 bg-slate-50/70 p-3"><p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Maintenance cost</p><p className="mt-2 text-xl font-black text-slate-900">{money(metrics.maintenanceCosts)}</p><p className="text-[10.5px] text-slate-500">Completed work-order costs</p></div></div><div className="mt-4 flex flex-wrap gap-2">{canManage && <ActionButton onClick={() => run("RUN_PROPERTY_CONTROLS", { limit: 500 })}><RefreshCw size={14} /> Run billing and expiry controls</ActionButton>}{canApprove && <ActionButton variant="secondary" onClick={() => setTab("finance")}><ClipboardCheck size={14} /> Review approvals</ActionButton>}<span className="rounded-xl border border-blue-100 bg-blue-50/60 px-3 py-2 text-[10.5px] text-blue-900">Recurring controls are idempotent. External reminders and payment confirmation require configured delivery/provider adapters.</span></div></Card><Card><h2 className="text-[15px] font-black text-slate-900">Upcoming lease expiries</h2><p className="mt-1 text-[11px] text-slate-500">Review and issue notices from the Leasing tab.</p><div className="mt-4 space-y-2">{upcomingLeases.map((lease) => <div key={lease.id} className="flex items-center justify-between gap-3 rounded-xl border border-slate-100 p-3"><div><p className="font-mono text-[11px] font-bold text-slate-800">{lease.leaseNumber}</p><p className="mt-1 text-[10.5px] text-slate-500">Expires {dateText(lease.endDate)} · {money(lease.rentAmount)}</p></div><Badge>{lease.status}</Badge></div>)}{!upcomingLeases.length && <p className="rounded-xl border border-dashed border-slate-200 p-6 text-center text-[11px] text-slate-400">No active lease expiries in the current snapshot.</p>}</div></Card></div>}
{tab === "portfolio" && <div className="grid gap-4 lg:grid-cols-2"><Card><div className="flex items-center justify-between"><h2 className="text-[15px] font-black text-slate-900">Buildings and locations</h2><Badge>{(snapshot.buildings || []).length} records</Badge></div><div className="mt-4 space-y-2">{(snapshot.buildings || []).map((row) => <div key={row.id} className="rounded-xl border border-slate-100 p-3"><div className="flex items-start justify-between gap-2"><div><p className="font-mono text-[11px] font-bold text-slate-800">{row.propertyCode} · {row.name}</p><p className="mt-1 text-[10.5px] text-slate-500">{row.propertyType} · {row.portfolioName || "Portfolio unavailable"}</p><p className="mt-1 text-[10.5px] text-slate-500"><MapPin size={12} className="mr-1 inline" />{[row.address, row.region, row.district, row.ward].filter(Boolean).join(" · ") || "Address not supplied"}</p></div><Badge>{row.status}</Badge></div></div>)}{!snapshot.buildings?.length && <p className="rounded-xl border border-dashed border-slate-200 p-6 text-center text-[11px] text-slate-400">No properties have been registered.</p>}</div></Card><Card><div className="flex items-center justify-between"><h2 className="text-[15px] font-black text-slate-900">Units, apartments, houses, and spaces</h2><Badge>{(snapshot.units || []).length} records</Badge></div><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[640px] text-left text-[11px]"><thead className="border-b border-slate-100 text-[10px] uppercase tracking-wide text-slate-400"><tr><th className="pb-2">Unit</th><th className="pb-2">Type</th><th className="pb-2">Rent</th><th className="pb-2">Status</th></tr></thead><tbody>{(snapshot.units || []).map((row) => <tr key={row.id} className="border-b border-slate-50"><td className="py-3 font-mono font-bold">{row.unitCode}<br /><span className="font-sans font-normal text-slate-400">{row.buildingName}</span></td><td className="py-3">{row.unitType}</td><td className="py-3">{money(row.rentAmount)}</td><td className="py-3"><Badge>{row.status}</Badge></td></tr>)}{!snapshot.units?.length && <tr><td colSpan="4" className="py-8 text-center text-slate-400">No units registered.</td></tr>}</tbody></table></div></Card></div>}
{tab === "leasing" && <div className="grid gap-4 lg:grid-cols-[1.1fr_.9fr]"><Card><div className="flex items-center justify-between"><div><h2 className="text-[15px] font-black text-slate-900">Applications and leases</h2><p className="mt-1 text-[11px] text-slate-500">Application, approval, lease, move-in inspection, renewal, and termination evidence.</p></div><Badge>{(snapshot.leases || []).length} leases</Badge></div><div className="mt-4 space-y-2">{(snapshot.leases || []).map((row) => <div key={row.id} className="rounded-xl border border-slate-100 p-3"><div className="flex items-center justify-between gap-2"><p className="font-mono text-[11px] font-bold">{row.leaseNumber}</p><Badge>{row.status}</Badge></div><p className="mt-1 text-[10.5px] text-slate-500">{dateText(row.startDate)} – {dateText(row.endDate)} · {money(row.rentAmount)} / {row.rentFrequency} · deposit {money(row.depositAmount)}</p>{canManage && row.status === "Pending Approval" && <ActionButton onClick={() => run("APPROVE_LEASE", { leaseId: row.id, note: "Approved after lease review" })}><CheckCircle2 size={14} /> Approve lease</ActionButton>}</div>)}{!snapshot.leases?.length && <p className="rounded-xl border border-dashed border-slate-200 p-6 text-center text-[11px] text-slate-400">No leases recorded.</p>}</div></Card><Card><h2 className="text-[15px] font-black text-slate-900">Tenant directory</h2><div className="mt-4 grid gap-2 sm:grid-cols-2">{(snapshot.tenants || []).map((row) => <div key={row.id} className="rounded-xl border border-slate-100 p-3"><div className="flex items-start justify-between gap-2"><div><p className="text-[11.5px] font-bold">{row.fullName}</p><p className="mt-1 text-[10.5px] text-slate-500">{row.tenantCode} · {row.phone}</p></div><Badge>{row.kycStatus}</Badge></div></div>)}{!snapshot.tenants?.length && <p className="col-span-full text-[11px] text-slate-400">No tenant records in this scope.</p>}</div></Card></div>}
{tab === "billing" && <Card><div className="flex items-center justify-between"><div><h2 className="text-[15px] font-black text-slate-900">Rent, utilities, deposits, and payment evidence</h2><p className="mt-1 text-[11px] text-slate-500">Issued invoices, posted cash, provider-pending intents, receipts, and arrears remain distinct.</p></div><Badge>{(snapshot.invoices || []).length} invoices</Badge></div><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[840px] text-left text-[11px]"><thead className="border-b border-slate-100 text-[10px] uppercase tracking-wide text-slate-400"><tr><th className="pb-2">Invoice</th><th className="pb-2">Type</th><th className="pb-2">Due</th><th className="pb-2">Total</th><th className="pb-2">Paid</th><th className="pb-2">Balance</th><th className="pb-2">Status</th></tr></thead><tbody>{(snapshot.invoices || []).map((row) => <tr key={row.id} className="border-b border-slate-50"><td className="py-3 font-mono font-bold">{row.invoiceNumber}</td><td className="py-3">{row.invoiceType}</td><td className="py-3">{dateText(row.dueDate)}</td><td className="py-3">{money(row.totalAmount)}</td><td className="py-3">{money(row.amountPaid)}</td><td className="py-3 font-bold">{money(Math.max(0, Number(row.totalAmount || 0) - Number(row.amountPaid || 0)))}</td><td className="py-3"><Badge>{row.status}</Badge></td></tr>)}{!snapshot.invoices?.length && <tr><td colSpan="7" className="py-8 text-center text-slate-400">No property invoices recorded.</td></tr>}</tbody></table></div></Card>}
{tab === "maintenance" && <div className="grid gap-4 lg:grid-cols-[1.1fr_.9fr]"><Card><div className="flex items-center justify-between"><div><h2 className="text-[15px] font-black text-slate-900">Maintenance request queue</h2><p className="mt-1 text-[11px] text-slate-500">Requests and work orders are persisted independently for assignment and expense control.</p></div><Badge>{(snapshot.maintenanceRequests || []).length} requests</Badge></div><div className="mt-4 space-y-2">{(snapshot.maintenanceRequests || []).map((row) => <div key={row.id} className="rounded-xl border border-slate-100 p-3"><div className="flex items-start justify-between gap-2"><div><p className="font-mono text-[11px] font-bold">{row.requestNumber} · {row.title}</p><p className="mt-1 text-[10.5px] text-slate-500">{row.category} · {row.description}</p></div><Badge>{row.priority}</Badge></div><div className="mt-2 flex items-center justify-between"><Badge>{row.status}</Badge>{canManage && row.status === "Open" && <ActionButton onClick={() => setComposer("ASSIGN_WORK_ORDER")}>Assign work order</ActionButton>}</div></div>)}{!snapshot.maintenanceRequests?.length && <p className="rounded-xl border border-dashed border-slate-200 p-6 text-center text-[11px] text-slate-400">No maintenance requests.</p>}</div></Card><Card><h2 className="text-[15px] font-black text-slate-900">Work orders and costs</h2><div className="mt-4 space-y-2">{(snapshot.workOrders || []).map((row) => <div key={row.id} className="rounded-xl border border-slate-100 p-3"><div className="flex items-center justify-between gap-2"><p className="font-mono text-[11px] font-bold">{row.workOrderNumber}</p><Badge>{row.status}</Badge></div><p className="mt-1 text-[10.5px] text-slate-500">Estimated {money(row.estimatedCost)} · actual {money(row.actualCost)}</p>{canManage && row.status !== "Completed" && <ActionButton onClick={() => setComposer("COMPLETE_WORK_ORDER")}>Complete work order</ActionButton>}</div>)}{!snapshot.workOrders?.length && <p className="text-[11px] text-slate-400">No work orders assigned.</p>}</div></Card></div>}
{tab === "finance" && <div className="grid gap-4 lg:grid-cols-2"><Card><h2 className="text-[15px] font-black text-slate-900">Finance control queue</h2><div className="mt-4 grid gap-3 sm:grid-cols-2"><div className="rounded-xl border border-slate-100 p-3"><p className="text-[10px] uppercase tracking-wide text-slate-400">Expenses</p><p className="mt-2 text-xl font-black">{money(metrics.propertyExpenses)}</p><p className="text-[10.5px] text-slate-500">Approved or paid property expenses</p></div><div className="rounded-xl border border-slate-100 p-3"><p className="text-[10px] uppercase tracking-wide text-slate-400">Maintenance cost</p><p className="mt-2 text-xl font-black">{money(metrics.maintenanceCosts)}</p><p className="text-[10.5px] text-slate-500">Completed work-order actual costs</p></div></div><div className="mt-4 space-y-2">{(snapshot.expenses || []).map((row) => <div key={row.id} className="flex items-center justify-between gap-3 rounded-xl border border-slate-100 p-3"><div><p className="font-mono text-[11px] font-bold">{row.expenseNumber} · {row.category}</p><p className="mt-1 text-[10.5px] text-slate-500">{row.description} · {money(row.amount)}</p></div><div className="flex items-center gap-2"><Badge>{row.status}</Badge>{canApprove && row.status === "Pending Approval" && <ActionButton onClick={() => run("APPROVE_EXPENSE", { expenseId: row.id, note: "Approved after finance review" })}>Approve</ActionButton>}</div></div>)}{!snapshot.expenses?.length && <p className="text-[11px] text-slate-400">No expense evidence in this scope.</p>}</div></Card><Card><h2 className="text-[15px] font-black text-slate-900">Reconciliation</h2><p className="mt-1 text-[11px] text-slate-500">Payment expected/actual variance is persisted for review.</p><div className="mt-4 space-y-2">{(snapshot.reconciliations || []).map((row) => <div key={row.id} className="flex items-center justify-between gap-3 rounded-xl border border-slate-100 p-3"><div><p className="text-[11px] font-bold">{row.paymentId || "Payment"}</p><p className="mt-1 text-[10.5px] text-slate-500">Expected {money(row.expectedAmount)} · actual {money(row.actualAmount)} · variance {money(row.variance)}</p></div><Badge>{row.status}</Badge></div>)}{!snapshot.reconciliations?.length && <p className="text-[11px] text-slate-400">No reconciliation records yet.</p>}</div></Card></div>}
{tab === "documents" && <div className="grid gap-4 lg:grid-cols-[1.1fr_.9fr]"><Card><div className="flex items-center justify-between"><h2 className="text-[15px] font-black text-slate-900">Property documents</h2><ActionButton variant="secondary" onClick={() => setUploadOpen(true)}><UploadCloud size={14} /> Upload</ActionButton></div><p className="mt-1 text-[11px] text-slate-500">Title, lease, KYC, insurance, inspection, and maintenance evidence is stored as metadata plus a secure storage key.</p><div className="mt-4 space-y-2">{(snapshot.documents || []).map((row) => <div key={row.id} className="flex items-center justify-between gap-3 rounded-xl border border-slate-100 p-3"><div><p className="text-[11px] font-bold">{row.title}</p><p className="mt-1 text-[10.5px] text-slate-500">{row.entityType} · {row.documentType} · expires {dateText(row.expiresAt)}</p></div><Badge>{row.verificationStatus}</Badge></div>)}{!snapshot.documents?.length && <p className="rounded-xl border border-dashed border-slate-200 p-6 text-center text-[11px] text-slate-400">No property documents registered.</p>}</div></Card><Card><h2 className="text-[15px] font-black text-slate-900">Ownership and compliance</h2><div className="mt-4 space-y-2">{(snapshot.owners || []).map((row) => <div key={row.id} className="flex items-center justify-between rounded-xl border border-slate-100 p-3"><span className="text-[11px] font-bold">{row.legalName}</span><Badge>{row.kycStatus}</Badge></div>)}{!snapshot.owners?.length && <p className="text-[11px] text-slate-400">No owner records in this scope.</p>}</div></Card></div>}
{tab === "reports" && <div className="grid gap-4 lg:grid-cols-2"><Card><h2 className="text-[15px] font-black text-slate-900">Portfolio performance</h2><div className="mt-4 grid gap-2 sm:grid-cols-2"><div className="rounded-xl border border-slate-100 p-3"><p className="text-[10px] uppercase tracking-wide text-slate-400">Collection exposure</p><p className="mt-2 text-xl font-black">{money(metrics.outstandingRent)}</p><p className="text-[10.5px] text-slate-500">Outstanding rent and charges</p></div><div className="rounded-xl border border-slate-100 p-3"><p className="text-[10px] uppercase tracking-wide text-slate-400">Open work</p><p className="mt-2 text-xl font-black">{metrics.openMaintenance ?? 0}</p><p className="text-[10.5px] text-slate-500">Maintenance requests</p></div><div className="rounded-xl border border-slate-100 p-3"><p className="text-[10px] uppercase tracking-wide text-slate-400">Upcoming expiries</p><p className="mt-2 text-xl font-black">{metrics.upcomingLeaseExpiries ?? 0}</p><p className="text-[10.5px] text-slate-500">Next 90 days</p></div><div className="rounded-xl border border-slate-100 p-3"><p className="text-[10px] uppercase tracking-wide text-slate-400">Property expenses</p><p className="mt-2 text-xl font-black">{money(metrics.propertyExpenses)}</p><p className="text-[10.5px] text-slate-500">Approved and paid</p></div></div></Card><Card><h2 className="text-[15px] font-black text-slate-900">Audit trail</h2><div className="mt-4 space-y-2">{(snapshot.audit || []).slice(0, 12).map((row) => <div key={row.id} className="rounded-xl border border-slate-100 p-3"><div className="flex items-center justify-between gap-2"><p className="text-[11px] font-bold">{row.action}</p><span className="text-[10px] text-slate-400">{dateTime(row.createdAt)}</span></div><p className="mt-1 text-[10.5px] text-slate-500">{row.entityType} · {row.entityId || "Tenant event"}</p></div>)}{!snapshot.audit?.length && <p className="text-[11px] text-slate-400">Audit history is unavailable or not included for this role.</p>}</div></Card></div>}</>}{composer && <Composer kind={composer} snapshot={snapshot} mutate={action} close={() => setComposer(null)} />}{uploadOpen && <UploadPanel snapshot={snapshot} upload={upload} close={() => setUploadOpen(false)} />}</div>;
}
